import {domLab} from './lab-kit.js';
import {variableFont,variableFontLicense} from './font-data.js';
const c=(key,label,min,max,value,step=1)=>({key,label,min,max,value,step});
const meta=(id,category,name,ja,description,tip,tags,categories=[category])=>({id,category,categories,name,ja,description,tip,prompt:tip,use:category==='layout'?'カードや読み物の構成、情報の見せ方。':category==='type'?'見出し、タイポグラフィ、文字の表情。':'印刷物のような質感、画像や背景の表現。',tags,source:category==='type'?'https://developer.mozilla.org/en-US/docs/Web/CSS/Guides/Fonts/Variable_fonts':'https://developer.mozilla.org/en-US/docs/Web/CSS'});
function editorial({root,values:v,kind}){const stage=root.querySelector('.lab-scene'),status=root.querySelector('.lab-status');let changed=false;return {update(){for(const[k,x]of Object.entries(v))stage.style.setProperty('--'+k,String(x));if(kind==='type-variable'){root.querySelector('.editorial-word').style.fontVariationSettings=`"wght" ${v.weight}`;}if(kind==='texture-grain')root.querySelector('feTurbulence').setAttribute('baseFrequency',String(v.frequency));if(kind==='layout-intrinsic')root.querySelector('.layout-board').style.width=v.width+'%';status.textContent=kind==='type-variable'?'Inter variable / wght '+v.weight:'';},action(){changed=!changed;stage.classList.toggle('changed',changed);if(kind==='type-variable'){root.querySelector('.editorial-word').style.fontVariationSettings=`"wght" ${changed?400:v.weight}`;status.textContent=changed?'比較 / wght 400':'選んだ太さ / wght '+v.weight;}else status.textContent=changed?'変化後':'元の状態';}}}
export const editorialLabs=[];
const typeCSS='.lab-scene{display:grid;place-items:center}.editorial-word{font:bold 58px Arial;letter-spacing:-4px;display:flex;align-items:center;justify-content:center;width:100%;height:100%;text-align:center}.editorial-word i{font-style:normal;display:inline-block}.editorial-word small{font-size:12px;letter-spacing:.1em}';
let variable=domLab(meta('type-variable','type','Variable font weight','文字の太さを連続して変える','一つのフォント内の可変軸を使い、文字の太さを400から900まで連続して変えます。','太さをゆっくり動かし、線の太さと文字の幅がどう変わるか見てください。',['文字','可変フォント','太さ','wght']),editorial,[c('weight','文字の太さ',400,900,600)],'<div class="editorial-word" style="font-family:ExpressionVF,Arial,sans-serif">MIXWELL</div>',`@font-face{font-family:ExpressionVF;src:url(${variableFont}) format('woff2');font-weight:400 900;font-display:swap}${typeCSS}.editorial-word{font-size:42px;letter-spacing:-2px}`,{static:true,action:'比較する'});
variable.code=variable.code.replace('<html lang="ja">',`<html lang="ja"><!-- ${variableFontLicense.replaceAll('--','—')} -->`);editorialLabs.push(variable);
editorialLabs.push(domLab(meta('type-kinetic','type','Kinetic typography','文字ごとに波を渡す','各文字の位相をずらし、文字列全体に波のような動きをつくります。','振幅0と大きな振幅を比較し、読める範囲を探してください。',['文字','キネティック','波','時間差'],['type','rhythm','motion']),editorial,[c('height','振幅 px',0,25,15),c('speed','周期 秒',1,5,2,.1)],'<div class="editorial-word" aria-label="NAOYAMAN">'+[...'NAOYAMAN'].map((l,i)=>`<i aria-hidden="true" style="--i:${i}">${l}</i>`).join('')+'</div>',typeCSS+'.editorial-word{font-size:clamp(22px,7vw,38px);letter-spacing:-.055em}.editorial-word i{animation:kinetic calc(var(--speed,2)*1s) ease-in-out infinite;animation-delay:calc(var(--i)*-.15s)}.changed i{animation-direction:reverse}@keyframes kinetic{50%{transform:translateY(calc(var(--height,15)*-1px))}}',{action:'動きを反転'}));
editorialLabs.push(domLab(meta('type-disassemble','type','Type disassembly','文字を分解して組み直す','文字ごとの移動量と回転量を変え、散った文字を一行へ戻します。','進行0と100の途中に、読める形が残るか探してください。',['文字','分解','再構成','変形'],['type','morph']),editorial,[c('progress','分解の進行 %',0,100,40)],'<div class="editorial-word" aria-label="good.">'+[...'good.'].map((l,i)=>`<i aria-hidden="true" style="--i:${i-2};--sign:${i%2?1:-1}">${l}</i>`).join('')+'</div>',typeCSS+'.editorial-word i{transform:translate(calc(var(--i)*var(--progress,40)*.2px),calc(var(--sign)*var(--progress,40)*.3px)) rotate(calc(var(--i)*var(--progress,40)*.3deg))}.changed i{opacity:.25}',{static:true,action:'輪郭を見比べる'}));
editorialLabs.push(domLab(meta('type-picture','type','Typographic image','文字の密度で絵をつくる','同じ文字を敷き詰め、文字の内側へ明暗の模様を映します。','文字の大きさを変え、近くでは文字、遠くでは絵になる境目を探す。',['文字','密度','絵','マスク'],['type','image','mask']),editorial,[c('size','文字の大きさ px',7,22,12)],'<div class="type-picture">'+('GOOD EXPRESSION '.repeat(55))+'</div>',typeCSS+'.type-picture{width:100%;height:140px;overflow:hidden;font:bold calc(var(--size,12)*1px)/1 monospace;word-break:break-all;background:radial-gradient(ellipse at 45% 45%,#ddd 0 24%,#222 25% 38%,#bbb 39% 50%,#111 51%);background-clip:text;-webkit-background-clip:text;color:transparent}.changed .type-picture{background-size:140% 140%}',{static:true,action:'構図を変える'}));
const artwork='<div class="paper-art"><span>EXPRESSION / 01</span><b>good<br>things.</b><i></i></div>';
const artCSS='.paper-art{position:absolute;inset:0;background:#e8e3d7;padding:12px 20px;overflow:hidden}.paper-art>span{position:relative;z-index:2;font:9px monospace;letter-spacing:.1em}.paper-art>b{position:relative;z-index:2;font:bold 37px/.9 Arial;letter-spacing:-2px;display:block;margin-top:10px}.paper-art>i{position:absolute;right:18%;top:22px;width:92px;height:92px;border-radius:50%;background:#898b83}.changed .paper-art{background:#d0d0cb}';
editorialLabs.push(domLab(meta('texture-grain','texture','Print grain','粒状感を重ねる','SVGのノイズを低い不透明度で重ね、均一な面へ細かなばらつきを加えます。','不透明度を0にして、ノイズがある時とない時を比べる。',['質感','粒状感','印刷','ノイズ'],['texture','image','generative']),editorial,[c('opacity','粒の濃さ %',0,70,30),c('frequency','粒の細かさ',.05,1,.7,.05)],artwork+'<svg class="grain" width="100%" height="100%" aria-hidden="true"><filter id="lab-grain"><feTurbulence type="fractalNoise" baseFrequency=".7" numOctaves="3" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/></filter><rect width="100%" height="100%" filter="url(#lab-grain)"/></svg>',artCSS+'.grain{position:absolute;inset:0;opacity:calc(var(--opacity,30)/100);mix-blend-mode:multiply;pointer-events:none}',{static:true,action:'紙色を変える'}));
editorialLabs.push(domLab(meta('texture-paper','texture','Paper folds','折り目から紙を感じる','細い陰影と色の差を重ね、平面へ折り目のような手がかりを与えます。','折り目の位置と濃さを変え、素材に見える強さを探す。',['紙','折り目','陰影','質感'],['texture','shadow']),editorial,[c('fold','折り目の位置 %',20,80,50),c('opacity','折り目の濃さ %',0,80,35)],artwork,artCSS+'.paper-art:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent calc(var(--fold,50)*1% - 5%),#fff calc(var(--fold,50)*1% - .5%),#555 calc(var(--fold,50)*1%),transparent calc(var(--fold,50)*1% + 7%));opacity:calc(var(--opacity,35)/100);pointer-events:none}',{static:true,action:'紙色を変える'}));
editorialLabs.push(domLab(meta('texture-registration','texture','Print misregistration','版のずれを見せる','同じ文字を異なる位置へ重ね、印刷の版ずれに似た縁をつくります。','ずれを0へ戻してから広げ、輪郭の変化を比べてください。',['印刷','版ずれ','文字','重なり'],['texture','type','blend']),editorial,[c('offset','版のずれ px',0,12,4,.5)],'<div class="registration"><b>PRINT</b><b aria-hidden="true">PRINT</b></div>','.lab-scene{isolation:isolate}.registration{position:absolute;inset:0;display:grid;place-items:center}.registration b{position:absolute;font:bold 62px Arial;letter-spacing:-5px;color:#637c8c;mix-blend-mode:multiply}.registration b+b{color:#a88a79;transform:translate(calc(var(--offset,4)*1px),calc(var(--offset,4)*.5px))}.changed b+b{mix-blend-mode:difference}',{static:true,action:'合成を変える'}));
editorialLabs.push(domLab(meta('image-collage','image','Cut-paper collage','切った形を重ねる','切り抜き、傾き、重なり、影を組み合わせて、紙片を並べたように構成します。','傾きと重なりを変え、同じ素材で構図をつくる。',['コラージュ','切り絵','紙','画像'],['image','texture','layout']),editorial,[c('rotation','紙片の傾き',-20,20,-7),c('overlap','重なり px',-30,50,15)],'<div class="collage-back"></div><div class="collage-cut"><b>good.</b></div><span class="collage-label">CUT / MIX / EDIT</span>','.collage-back{position:absolute;width:140px;height:115px;left:18%;top:10px;background:repeating-linear-gradient(45deg,#aaa 0 3px,#ddd 3px 8px);transform:rotate(8deg)}.collage-cut{position:absolute;left:calc(40% - var(--overlap,15)*1px);top:20px;width:145px;height:100px;background:#333;color:#eee;clip-path:polygon(0 5%,15% 0,30% 7%,48% 1%,68% 5%,85% 0,100% 8%,96% 100%,80% 95%,60% 100%,40% 94%,20% 100%,0 96%);display:grid;place-items:center;transform:rotate(calc(var(--rotation,-7)*1deg))}.collage-cut b{font:bold 42px Arial;letter-spacing:-3px}.collage-label{position:absolute;bottom:8px;left:20px;font:9px monospace}.changed .collage-back{transform:rotate(-8deg)}',{static:true,action:'構図を変える'}));
const board='<div class="layout-board">'+Array.from({length:6},(_,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><span>something good.</span></div>`).join('')+'</div>';
const boardCSS='.lab-scene{display:grid;place-items:center}.layout-board{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;width:100%;padding:8px;height:130px}.layout-board>div{border:1px solid #aaa;background:#f8f8f5;padding:8px;min-width:0;overflow:hidden}.layout-board b{font:bold 22px Arial;display:block}.layout-board span{font:8px Arial;display:block;margin-top:4px}.changed .layout-board>div:nth-child(2n){background:#333;color:white}';
for(const [id,name,ja,description,tip,controls,css]of[
 ['layout-intrinsic','Intrinsic grid','入るだけの列をつくる','最小幅を決め、領域に収まる列数をCSS Gridに選ばせます。','幅を変え、特定の端末名によらず列数が変わる様子を見る。',[c('width','領域の幅 %',40,100,100)],'.layout-board{grid-template-columns:repeat(auto-fit,minmax(65px,1fr));height:auto;max-height:138px}'],
 ['layout-density','Layout density','余白で情報の密度を変える','同じ六つの項目を、間隔だけ変えて並べます。','余白を増やした時、まとまりと読みやすさはどう変わる？',[c('gap','項目の間隔 px',0,20,5)],'.layout-board{gap:calc(var(--gap,5)*1px)}'],
 ['layout-alignment','Alignment rhythm','整列を少し崩す','共通の基準線から要素をずらし、揃う部分と崩れる部分を比較します。','ずれを0へ戻し、どこに秩序を感じるか比べる。',[c('shift','交互のずれ px',0,24,12)],'.layout-board>div:nth-child(2n){transform:translateY(calc(var(--shift,12)*1px))}.layout-board{height:110px;margin-top:-20px}'],
 ['layout-hierarchy','Visual hierarchy','大きさで読む順序をつくる','一つの要素だけを大きくし、同じ内容の中へ視覚的な優先順位をつくります。','主役の大きさを変え、最初に見てしまう場所を観察する。',[c('weight','先頭の文字サイズ px',15,45,35)],'.layout-board>div:first-child b{font-size:calc(var(--weight,35)*1px)}']
])editorialLabs.push(domLab(meta(id,'layout',name,ja,description,tip,['レイアウト','余白','構成','比較']),editorial,controls,board,boardCSS+css,{static:true,action:'明暗を入れ替える'}));
